class Solution {
public:
    int minLength(string s, int numOps) {
        int n = s.length();
        auto check = [&](int m) {
            if (m == 1) {
                int d1 = 0, d2 = 0;
                for (int i = 0; i < n; ++i) {
                    if (s[i] != (i % 2 == 0 ? '0' : '1')) d1++;
                    if (s[i] != (i % 2 == 0 ? '1' : '0')) d2++;
                }
                return min(d1, d2) <= numOps;
            }
            int ops = 0;
            int i = 0;
            while (i < n) {
                int j = i;
                while (j < n && s[j] == s[i]) j++;
                int len = j - i;
                ops += len / (m + 1);
                i = j;
            }
            return ops <= numOps;
        };

        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minLength(String s, int numOps) {
        int n = s.length();
        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(s, numOps, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private boolean check(String s, int numOps, int m) {
        int n = s.length();
        if (m == 1) {
            int d1 = 0, d2 = 0;
            for (int i = 0; i < n; ++i) {
                if (s.charAt(i) != (i % 2 == 0 ? '0' : '1')) d1++;
                if (s.charAt(i) != (i % 2 == 0 ? '1' : '0')) d2++;
            }
            return Math.min(d1, d2) <= numOps;
        }
        int ops = 0;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            int len = j - i;
            ops += len / (m + 1);
            i = j;
        }
        return ops <= numOps;
    }
}

var minLength = function(s, numOps) {
    const n = s.length;
    const check = (m) => {
        if (m === 1) {
            let d1 = 0, d2 = 0;
            for (let i = 0; i < n; ++i) {
                if (s[i] !== (i % 2 === 0 ? '0' : '1')) d1++;
                if (s[i] !== (i % 2 === 0 ? '1' : '0')) d2++;
            }
            return Math.min(d1, d2) <= numOps;
        }
        let ops = 0;
        let i = 0;
        while (i < n) {
            let j = i;
            while (j < n && s[j] === s[i]) j++;
            ops += Math.floor((j - i) / (m + 1));
            i = j;
        }
        return ops <= numOps;
    };

    let low = 1, high = n, ans = n;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (check(mid)) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
